// Isolated, explicitly scripted investigation. Does not mutate billing records.
let investigationStep=0;
function investigationPanel(){return `<section class="panel pad"><div class="section-head"><h2>${tr('Investigate changing evidence','बदलते सबूत की जाँच')}</h2><span class="badge">${tr('Interactive scenario · scripted','इंटरैक्टिव उदाहरण · पूर्वनिर्धारित')}</span></div><p>${tr('Explore how a proposed AI investigator would revise a conclusion as new records arrive. This separate example uses an explicitly agreed ₹20 unit rate; it does not change the fixed-fee Nila case.','नए रिकॉर्ड आने पर प्रस्तावित AI कैसे निष्कर्ष बदलेगा, देखें। इस अलग उदाहरण में ₹20 प्रति कार्टन की स्वीकृत दर है; Nila का निश्चित शुल्क नहीं बदलता।')}</p>${button(tr('Open investigation','जाँच खोलें'),'investigation-open','primary')}</section>`}
function showInvestigation(){
const hi=state.settings?.language==='hi';
const records=[
['E-101 · 5 Oct, 10:00 · Customer email','Apply festive sleeves to 120 cartons at ₹20 per carton.'],
['W-102 · 5 Oct, 14:20 · Customer WhatsApp','Cancel the last 20. Go ahead with the rest at the same rate.'],
['D-103 · 6 Oct, 16:10 · Dispatch record','Festival pack adaptation completed: 100 cartons, batch B17.'],
['I-104 · 7 Oct, 09:00 · Invoice register','Batch B17: transport only. No packaging line.'],
['E-105 · 7 Oct, 11:00 · Customer email','I thought this was covered by our package. Please check before billing.'],
['E-106 · 7 Oct, 15:00 · Simulated clarification','Packaging was separate from transport. Confirming 100 cartons at ₹20.']];
const count=[1,4,5,6][investigationStep];
const findings=[
'Initial request: 120 cartons × ₹20 = ₹2,400. Completion and prior billing have not been checked. Do not bill.',
'Revised candidate: 100 completed cartons × ₹20 = ₹2,000. The later cancellation changes the scope. Merchant verification is still required.',
'Proposal on hold. The customer disputes whether packaging was included. Do not treat the earlier agreement as sufficient.',
'Candidate restored for merchant review: ₹2,000. The clarification supports separate pricing; verify all source records before preparing an invoice.'
];
openModal(tr('AI investigation','AI जाँच'),`<div data-i18n-preserve><p class="notice">Scripted scenario, not live AI. No message is sent and no invoice or dashboard total is changed.</p><div class="investigation-layout"><div><h3>Source records</h3>${records.slice(0,count).map((r,i)=>`<details class="investigation-record" ${i===count-1?'open':''}><summary>${r[0]}</summary><blockquote>${r[1]}</blockquote></details>`).join('')}</div><div aria-live="polite"><h3>Current finding</h3><p class="notice ${investigationStep===2?'warning':''}">${findings[investigationStep]}</p><h3>Evidence assessment</h3><p>${investigationStep===0?'Missing: completion proof and invoice check. Next search: later customer messages and batch B17 dispatch records.':investigationStep===1?'Supports: E-101 rate, W-102 revised scope, D-103 completion and I-104 invoice omission. Unresolved: merchant must verify these records refer to the same service.':investigationStep===2?'Conflict: E-105 challenges separate billability. Clarify the package scope before any financial action.': 'E-106 resolves the package question in this example. A customer reply is supporting evidence, not automatic permission to invoice.'}</p>${investigationStep===2?'<label class="field">Review clarification draft<textarea id="investigation-question">For batch B17, was packaging included in the transport package, or separately agreed at ₹20 per carton for the 100 completed cartons?</textarea></label><p class="small">Editable draft only. Continue below to inspect a simulated reply.</p>':''}<details><summary>Why interpretation helps</summary><p>An exact-ID or keyword rule misses differently named work. A synonym rule alone does not resolve which message supersedes another or whether a later package objection changes billability. Tailored rules can handle this known example; AI must demonstrate better generalisation on unseen records.</p><p>The proposed model searches permitted records, extracts scope and conflicts with source IDs, and requests clarification. Code calculates the amount and enforces permissions and approval gates.</p></details></div></div><div class="modal-actions">${investigationStep>0?button('Previous evidence','investigation-back'):''}${investigationStep<3?button(['Find completion & later messages','Add conflicting customer message','Inspect simulated clarification'][investigationStep],'investigation-next','primary'):button('Restart investigation','investigation-open')}</div></div>`);
}
function handleInvestigation(e){const a=e.target.closest('[data-action]')?.dataset.action;if(!a?.startsWith('investigation-'))return;if(a==='investigation-open')investigationStep=0;if(a==='investigation-next')investigationStep=Math.min(3,investigationStep+1);if(a==='investigation-back')investigationStep=Math.max(0,investigationStep-1);if(modal.open)modal.close();showInvestigation();}


